use ndarray::{aview0, aview1, arr2, Axis};

let a = arr2(&[[1., 2., 3.],
               [4., 5., 6.]]);

assert!(
    a.product_axis(Axis(0)) == aview1(&[4., 10., 18.]) &&
    a.product_axis(Axis(1)) == aview1(&[6., 120.]) &&

    a.product_axis(Axis(0)).product_axis(Axis(0)) == aview0(&720.)
